//! The bootstrap oracle: every corpus program is elaborator-checked, built, and
//! (when `wasmtime` is available) run. The golden report is generated by a
//! separate process, so any dependence on process-local state shows up here.

#![cfg(not(target_family = "wasm"))]

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

#[test]
fn corpus_report_matches_the_golden() {
    let root = root();
    let actual = neo::oracle::corpus_report(&root).expect("corpus report");
    assert!(
        !actual.contains("\tbuild-error\t"),
        "the corpus contains a code generation failure:\n{actual}"
    );
    let golden = fs::read_to_string(root.join("tests/corpus.txt")).expect("read tests/corpus.txt");
    assert_eq!(
        actual,
        golden,
        "the compiler report changed. Review the diff, then regenerate with:\n\
         \tcargo run --bin neo-internal -- corpus {} > tests/corpus.txt",
        root.display()
    );
}

#[test]
fn components_are_deterministic() {
    let root = root();
    for path in neo::oracle::corpus_files(&root).expect("corpus files") {
        let source = fs::read_to_string(&path).expect("read corpus file");
        let Ok(globals) = neo::oracle::elaborate(&source) else {
            continue;
        };
        let Ok(first) = neo::codegen::build_component_bytes(&globals) else {
            continue;
        };
        let second = neo::codegen::build_component_bytes(&globals).expect("second build");
        assert_eq!(first, second, "{} is not deterministic", path.display());
    }
}

/// Accepted corpus programs, in golden order.
fn accepted_programs(root: &Path) -> Vec<(PathBuf, String)> {
    let golden = fs::read_to_string(root.join("tests/corpus.txt")).expect("read tests/corpus.txt");
    let mut out = Vec::new();
    for line in golden.lines() {
        let mut fields = line.split('\t');
        let relative = fields.next().unwrap_or_default();
        if fields.next() == Some("ok") {
            out.push((root.join(relative), relative.to_string()));
        }
    }
    out
}

#[test]
fn codegen_matches_the_interpreter() {
    if Command::new("wasmtime").arg("--version").output().is_err() {
        eprintln!("skipping: wasmtime is not available");
        return;
    }
    let root = root();
    let out_dir = std::env::temp_dir().join(format!("neo-oracle-{}", std::process::id()));
    fs::create_dir_all(&out_dir).expect("create temp dir");

    let programs = accepted_programs(&root);
    assert!(!programs.is_empty(), "the corpus is empty");

    for (path, relative) in programs {
        let interpreted = Command::new(env!("CARGO_BIN_EXE_neo"))
            .arg(&path)
            .output()
            .expect("run the interpreter");
        assert!(
            interpreted.status.code().is_some(),
            "{} failed to interpret:\n{}",
            relative,
            String::from_utf8_lossy(&interpreted.stderr)
        );

        let wasm = out_dir.join(format!("{}.wasm", relative.replace('/', "-")));
        let built = Command::new(env!("CARGO_BIN_EXE_neo"))
            .arg("build")
            .arg(&path)
            .arg("-o")
            .arg(&wasm)
            .output()
            .expect("run the compiler");
        assert!(
            built.status.success(),
            "{} failed to build:\n{}",
            relative,
            String::from_utf8_lossy(&built.stderr)
        );

        let compiled = Command::new("wasmtime")
            .arg(&wasm)
            .output()
            .expect("run wasmtime");
        assert!(
            compiled.status.code().is_some(),
            "{} failed under wasmtime:\n{}",
            relative,
            String::from_utf8_lossy(&compiled.stderr)
        );
        assert_eq!(
            interpreted.status.code(),
            compiled.status.code(),
            "{} exits differently when interpreted and compiled",
            relative
        );
        assert_eq!(
            interpreted.stdout, compiled.stdout,
            "{} prints differently when interpreted and compiled",
            relative
        );
    }
}
